node -e 'const fs=require("fs")
const fail=(m)=>{console.error(m);process.exit(1)}
const L=fs.readFileSync("app/layout.tsx","utf8")
if(!/__html:\s*POPOVER_DISMISS_SCRIPT/.test(L))fail("the root layout does not install the popup dismiss script, so details popups never close on an outside click")
const T=fs.readFileSync("components/ui/underline-tabs.tsx","utf8")
if(!/<details[^>]*data-popover/.test(T))fail("the underline-tabs More menu is not marked as a popup, so it stays hanging open")
const lib=fs.readFileSync("lib/ui/popover-dismiss.ts","utf8")
const m=lib.match(/POPOVER_DISMISS_SCRIPT = `([\s\S]*?)`\n/)
if(!m)fail("the dismiss script is gone")
const script=m[1].replace(/\$\{POPOVER_ATTR\}/g,"data-popover")
const {JSDOM}=require("jsdom")
const dom=new JSDOM("<details id=a data-popover open><summary id=sa>More</summary><a id=l href=#x>R</a></details><details id=c open><summary>Acc</summary></details><p id=o>x</p>",{runScripts:"outside-only"})
dom.window.eval(script)
const d=dom.window.document,$=(i)=>d.getElementById(i)
const click=(i)=>$(i).dispatchEvent(new dom.window.MouseEvent("click",{bubbles:true}))
click("o")
if($("a").hasAttribute("open"))fail("a popup stays open after a click outside it")
if(!$("c").hasAttribute("open"))fail("the dismiss closed a plain accordion, which is not a popup")
$("a").setAttribute("open","")
click("l")
if($("a").hasAttribute("open"))fail("a popup stays open after an item inside it is picked")
$("a").setAttribute("open","")
d.dispatchEvent(new dom.window.KeyboardEvent("keydown",{key:"Escape",bubbles:true}))
if($("a").hasAttribute("open"))fail("a popup stays open on Escape")
console.log("LIVE-745 ok")'
